_PROVENANCE_INITIALIZED_AT = datetime.now(UTC).isoformat()
_PROCESS_PID = os.getpid()
_PROCESS_LOCK = Lock()
_PROCESS_SETTINGS_SUMMARY: dict[str, Any] = {}


def _sha256_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def _file_hashes() -> dict[str, str | None]:
    result: dict[str, str | None] = {}
    for relative in _KEY_FILES:
        path = _REPO_ROOT / relative
        try:
            result[relative] = _sha256_bytes(path.read_bytes())
        except OSError:
            result[relative] = None
    return result


def _git_command(*args: str) -> tuple[bool, str]:
    try:
        value = subprocess.check_output(  # noqa: S603, S607
            ["git", *args],  # noqa: S607
            cwd=_REPO_ROOT,
            stderr=subprocess.DEVNULL,
            text=True,
        ).strip()
    except (OSError, subprocess.SubprocessError):
        return False, ""
    return True, value


def _git_snapshot() -> dict[str, Any]:
    available, status = _git_command("status", "--porcelain=v1", "--untracked-files=all")
    _, commit = _git_command("rev-parse", "HEAD")
    _, patch = _git_command("diff", "HEAD", "--binary")
    if not available:
        return {
            "available": False,
            "commit": None,
            "dirty": None,
            "dirty_status_hash": None,
            "dirty_patch_hash": None,
            "untracked_file_sha256": None,
        }
    untracked: dict[str, str] = {}
    for line in status.splitlines():
        if not line.startswith("?? "):
            continue
        relative = line[3:].strip()
        if relative not in _KEY_FILES:
            continue
        try:
            untracked[relative] = _sha256_bytes((_REPO_ROOT / relative).read_bytes())
        except OSError:
            untracked[relative] = "missing"
    return {
        "available": True,
        "commit": commit or None,
        "dirty": bool(status),
        "dirty_status_hash": _sha256_bytes(status.encode("utf-8")),
        "dirty_patch_hash": _sha256_bytes(patch.encode("utf-8")),
        "untracked_file_sha256": untracked,
    }


def _loaded_module_evidence() -> dict[str, dict[str, str | None]]:
    """Report loaded module paths without pretending their bytes were hashed."""
    names = (
        "bestseller.web.server",
        "bestseller.services.planner",
        "bestseller.services.conception",
        "bestseller.services.concept_tournament",
        "bestseller.services.book_design",
        "bestseller.services.pipelines",
    )
    evidence: dict[str, dict[str, str | None]] = {}
    for name in names:
        module = sys.modules.get(name)
        path = getattr(module, "__file__", None) if module is not None else None
        evidence[name] = {"loaded": "true" if module is not None else "false", "path": path}
    return evidence


def _settings_summary(settings: object | None) -> dict[str, Any]:
    if settings is None:
        return {}
    try:
        effective = settings
        from bestseller.settings import apply_runtime_llm_profile, runtime_llm_profile_payload

        effective = apply_runtime_llm_profile(settings)
        return {
            "llm_mock": bool(effective.llm.mock),
            "planner_model": str(effective.llm.planner.model),
            "writer_model": str(effective.llm.writer.model),
            "critic_model": str(effective.llm.critic.model),
            "editor_model": str(effective.llm.editor.model),
            "runtime_profile": runtime_llm_profile_payload(settings).get("active_key"),
        }
    except (AttributeError, TypeError):
        return {}


def _snapshot(
    *, source: str, files: dict[str, str | None], settings: object | None = None
) -> dict[str, Any]:
    return {
        "schema_version": RUNTIME_PROVENANCE_SCHEMA,
        "source": source,
        "pid": _PROCESS_PID,
        "provenance_initialized_at": _PROVENANCE_INITIALIZED_AT,
        "process_started_at": None,
        "process_started_at_basis": "unavailable; provenance initialized at Python module import",
        "captured_at": datetime.now(UTC).isoformat(),
        "git": _git_snapshot(),
        "key_file_sha256": files,
        "loaded_module_evidence": _loaded_module_evidence() if source == "process_start" else {},
        "settings": _settings_summary(settings),
    }


# This is deliberately captured at import time.  It is the process-side
# snapshot, and must not be recomputed from disk in /api/status.
_PROCESS_FILES = _file_hashes()
_PROCESS_GIT = _git_snapshot()
_PROCESS_BASE = {
    "schema_version": RUNTIME_PROVENANCE_SCHEMA,
    "source": "process_start",
    "pid": _PROCESS_PID,
    "provenance_initialized_at": _PROVENANCE_INITIALIZED_AT,
    "process_started_at": None,
    "process_started_at_basis": "unavailable; provenance initialized at Python module import",
    "captured_at": _PROVENANCE_INITIALIZED_AT,
    "git": _PROCESS_GIT,
    "key_file_sha256": _PROCESS_FILES,
    "loaded_module_evidence": _loaded_module_evidence(),
    "settings": {},
}


def initialize_process_runtime(settings: object | None = None) -> dict[str, Any]:
    """Attach startup settings to the immutable process provenance snapshot."""
    with _PROCESS_LOCK:
        if not _PROCESS_SETTINGS_SUMMARY:
            _PROCESS_SETTINGS_SUMMARY.update(_settings_summary(settings))
            _PROCESS_BASE["settings"] = dict(_PROCESS_SETTINGS_SUMMARY)
        return deepcopy(_PROCESS_BASE)


def process_runtime_provenance(settings: object | None = None) -> dict[str, Any]:
    return initialize_process_runtime(settings)


def disk_runtime_provenance(settings: object | None = None) -> dict[str, Any]:
    """Return an explicitly current disk snapshot, separate from process state."""
    return _snapshot(source="disk_current", files=_file_hashes(), settings=settings)


def task_runtime_provenance(
    task_id: str, task_started_at: str, settings: object | None = None
) -> dict[str, Any]:
    process = process_runtime_provenance(settings)
    return {
        "schema_version": RUNTIME_PROVENANCE_SCHEMA,
        "task_id": str(task_id),
        "task_started_at": str(task_started_at),
        "process": process,
    }


def process_runtime_reference(settings: object | None = None) -> dict[str, Any]:
    """Return a compact LLM receipt reference to the immutable process snapshot."""
    process = process_runtime_provenance(settings)
    material = {
        "schema_version": process["schema_version"],
        "pid": process["pid"],
        "provenance_initialized_at": process["provenance_initialized_at"],
        "git": process["git"],
        "key_file_sha256": process["key_file_sha256"],
        "settings": process.get("settings", {}),
    }
    fingerprint = _sha256_bytes(
        json.dumps(material, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode(
            "utf-8"
        )
    )
    return {
        "schema_version": RUNTIME_PROVENANCE_SCHEMA,
        "process_fingerprint": fingerprint,
        "process_pid": process["pid"],
        "provenance_initialized_at": process["provenance_initialized_at"],
        "source_snapshot_sha256": dict(process["key_file_sha256"]),
        "source_snapshot_basis": "process_import_snapshot",
    }


